def verify_oia024() -> None:
    if not OIA024.exists():
        raise RuntimeError(f"Actual OIA-024 production module missing: {OIA024}")
    source = OIA024.read_text(encoding="utf-8")
    required = [
        'SCHEMA_VERSION = "OIA-024"',
        'ENGINE_ID = "OIA-024"',
        'READINESS_POLICY_ID', 'READINESS_VERIFIED', 'ENTRY_READINESS_VERIFIED',
        'source_session_hash', 'source_activation_hash', 'source_claim_hash',
        'source_manifest_hash', 'source_batch_hash', 'readiness_entry_hash',
        'readiness_hash', 'read_only_corpus', 'research_execution_allowed',
        'qseries_handoff_allowed', 'market_order_creation_allowed',
        'funds_movement_allowed', 'portfolio_mutation_allowed',
    ]
    missing = [token for token in required if token not in source]
    if missing:
        raise RuntimeError(f"Actual OIA-024 production contract mismatch: {missing}")


def write_full_replacement(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(source.rstrip() + "\n", encoding="utf-8")
    print(f"[OK] FULL REPLACEMENT: {path}")


def update_init() -> None:
    source = INIT.read_text(encoding="utf-8") if INIT.exists() else "__all__ = []\n"
    marker = "from .oracle_qualified_research_worker_session_certification_gate import ("
    if marker not in source:
        source = source.rstrip() + "\n" + INIT_BLOCK
        INIT.write_text(source.rstrip() + "\n", encoding="utf-8")
        print(f"[OK] PACKAGE UPDATED: {INIT}")
    else:
        print(f"[OK] PACKAGE ALREADY CURRENT: {INIT}")


def main() -> int:
    print("=" * 40)
    print(" OIA-025 INSTALLER")
    print(" WORKER SESSION CERTIFICATION GATE")
    print(" READ-ONLY RESEARCH AUTHORITY BOUNDARY")
    print("=" * 40)
    verify_oia024()
    print("[OK] Actual OIA-024 readiness contract verified")
    write_full_replacement(PRODUCTION, PRODUCTION_SOURCE)
    write_full_replacement(TEST, TEST_SOURCE)
    update_init()
    py_compile.compile(str(PRODUCTION), doraise=True)
    py_compile.compile(str(TEST), doraise=True)
    py_compile.compile(str(INIT), doraise=True)
    print("[OK] Production, test, and package syntax verified")
    result = subprocess.run([sys.executable, str(TEST)], cwd=str(ROOT), check=False)
    if result.returncode != 0:
        raise SystemExit(result.returncode)
    print("[OK] OIA-025 test executed automatically")
    print()
    print("[DONE] OIA-025 worker session certification gate installed")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
